}

import { useState } from "react";
import { API_BASE } from "../lib/apiConfig";

interface LinkItem {
  url: string;
  anchor: string;
  nofollow: boolean;
  domain?: string;
}

interface QualityInfo {
  score: number;
  total: number;
  dofollow: number;
  nofollow: number;
  unique_domains: number;
  branded_anchors: number;
  generic_anchors: number;
  quality: string;
}

interface Domain {
  domain: string;
  links: number;
  dofollow: number;
  nofollow: number;
  anchors: string[];
}

interface BacklinkResult {
  url: string;
  overall_score: number;
  grade: string;
  internal_links: { total: number; quality: QualityInfo; sample: LinkItem[] };
  external_links: { total: number; quality: QualityInfo; sample: LinkItem[] };
  referring_domains: Domain[];
  total_domains: number;
  suggestions: string[];
}

export function BacklinkAnalyzer() {
  const [url, setUrl] = useState("");
  const [loading, setLoading] = useState(false);
