import { useState, useMemo } from "react";
import { API_BASE } from "../lib/apiConfig";

// ΓöÇΓöÇΓöÇ Types ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

interface LinkResult {
  url: string;
  source_page: string;
  status_code: number;
  link_type: string;  // "internal" | "external"
  status: string;     // "ok" | "broken" | "redirect"
}

interface ScanResult {
  url: string;
  total_links: number;
  ok_links: number;
  broken_links: number;
  redirect_links: number;
  broken_rate: number;
  links: LinkResult[];
}

type FilterTab = "all" | "broken" | "redirect" | "ok";

// ΓöÇΓöÇΓöÇ Helpers ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

/** Status row background color */
function statusRowBg(status: string): string {
  if (status === "broken") return "rgba(239,68,68,0.06)";
  if (status === "redirect") return "rgba(234,179,8,0.06)";
  return "transparent";
}

/** Status badge color */
function statusColor(status: string): string {
  if (status === "broken") return "#ef4444";
  if (status === "redirect") return "#eab308";
  return "#22c55e";
}

/** Status badge label in Vietnamese */
function statusLabel(status: string): string {
  if (status === "broken") return "Hß╗Ång";
  if (status === "redirect") return "Redirect";
  return "Tß╗æt";
}

/** Link type label */
function typeLabel(type: string): string {
  return type === "internal" ? "Nß╗Öi bß╗Ö" : "B├¬n ngo├ái";
}

/** Export data as CSV */
function exportCsv(links: LinkResult[], filename: string) {
  const header = "URL,Trang nguß╗ôn,Status Code,Loß║íi,Trß║íng th├íi\n";
  const rows = links.map(l =>
    `"${l.url}","${l.source_page}",${l.status_code},"${typeLabel(l.link_type)}","${statusLabel(l.status)}"`
  ).join("\n");
  const blob = new Blob([header + rows], { type: "text/csv;charset=utf-8;" });
  const a = document.createElement("a");
  a.href = URL.createObjectURL(blob);
  a.download = filename;
  a.click();
  URL.revokeObjectURL(a.href);
}

