import { useState, useEffect, useCallback } from "react";
import { API_BASE } from "../lib/apiConfig";

interface CalendarItem {
  id: number;
  title: string;
  description: string;
  content_type: string;
  status: string;
  scheduled_date: string;
  author: string;
  keywords: string;
  priority: string;
}

interface Stats {
  total: number;
  draft: number;
  review: number;
  published: number;
  upcoming: number;
  overdue: number;
}

interface TopicSuggestion {
  title: string;
