  review: { label: "─Éang duyß╗çt", color: "#f59e0b", bg: "rgba(245,158,11,0.12)" },
  published: { label: "─É├ú ─æ─âng", color: "#22c55e", bg: "rgba(34,197,94,0.12)" },
