  const [stats, setStats] = useState<Stats | null>(null);
  const [showForm, setShowForm] = useState(false);
  const [form, setForm] = useState({ title: "", description: "", content_type: "blog", scheduled_date: "", author: "", keywords: "", priority: "medium" });
