          <div className="spin-stat"><span className="spin-stat-label">─Éang duyß╗çt</span><span className="spin-stat-value" style={{ color: "#f59e0b" }}>{stats.review}</span></div>
          <div className="spin-stat"><span className="spin-stat-label">─É├ú ─æ─âng</span><span className="spin-stat-value" style={{ color: "#22c55e" }}>{stats.published}</span></div>
          {stats.overdue > 0 && <div className="spin-stat"><span className="spin-stat-label">Qu├í hß║ín</span><span className="spin-stat-value" style={{ color: "#ef4444" }}>{stats.overdue}</span></div>}
          {stats.upcoming > 0 && <div className="spin-stat"><span className="spin-stat-label">Sß║»p tß╗¢i</span><span className="spin-stat-value" style={{ color: "#8b5cf6" }}>{stats.upcoming}</span></div>}
        </div>
      )}

      {/* Actions */}
      <div className="geo-actions" style={{ marginTop: 16 }}>
        <button className="rt-btn rt-btn-add" onClick={() => setShowForm(!showForm)}>Γ₧ò Th├¬m b├ái viß║┐t</button>
        <button className="rt-btn rt-btn-sync" onClick={handleSuggest} disabled={suggestLoading}>
          {suggestLoading ? "ΓÅ│ ─Éang tß║ío..." : "≡ƒñû AI ─æß╗ü xuß║Ñt chß╗º ─æß╗ü"}
        </button>
        <div className="spin-version-tabs">
          {["", "draft", "review", "published"].map(s => (
            <button key={s} className={`spin-version-tab ${statusFilter === s ? "active" : ""}`}
              onClick={() => setStatusFilter(s)}>
              {s ? STATUS_META[s]?.label : "Tß║Ñt cß║ú"}
            </button>
          ))}
        </div>
      </div>

      {/* Add form */}
      {showForm && (
        <div className="rt-import-panel" style={{ marginTop: 12 }}>
          <div className="geo-schema-form">
            <div className="input-group">
              <label className="input-label">Ti├¬u ─æß╗ü *</label>
              <input className="text-input" value={form.title} onChange={e => setForm({ ...form, title: e.target.value })} placeholder="T├¬n b├ái viß║┐t..." style={{ paddingLeft: 12 }} />
            </div>
            <div className="input-group">
              <label className="input-label">Loß║íi</label>
              <select className="text-input" value={form.content_type} onChange={e => setForm({ ...form, content_type: e.target.value })} style={{ paddingLeft: 12 }}>
                {Object.entries(TYPE_LABELS).map(([k, v]) => <option key={k} value={k}>{v}</option>)}
              </select>
            </div>
            <div className="input-group">
              <label className="input-label">Ng├áy ─æ─âng</label>
              <input type="date" className="text-input" value={form.scheduled_date} onChange={e => setForm({ ...form, scheduled_date: e.target.value })} style={{ paddingLeft: 12 }} />
            </div>
            <div className="input-group">
              <label className="input-label">╞»u ti├¬n</label>
              <select className="text-input" value={form.priority} onChange={e => setForm({ ...form, priority: e.target.value })} style={{ paddingLeft: 12 }}>
                <option value="high">≡ƒö┤ Cao</option><option value="medium">≡ƒƒí Trung b├¼nh</option><option value="low">≡ƒö╡ Thß║Ñp</option>
              </select>
            </div>
            <div className="input-group" style={{ gridColumn: "1 / -1" }}>
              <label className="input-label">M├┤ tß║ú</label>
              <input className="text-input" value={form.description} onChange={e => setForm({ ...form, description: e.target.value })} placeholder="M├┤ tß║ú ngß║»n..." style={{ paddingLeft: 12 }} />
            </div>
            <div className="input-group">
              <label className="input-label">Keywords</label>
              <input className="text-input" value={form.keywords} onChange={e => setForm({ ...form, keywords: e.target.value })} placeholder="kw1, kw2" style={{ paddingLeft: 12 }} />
            </div>
            <div className="input-group">
              <label className="input-label">T├íc giß║ú</label>
