import { useState } from "react";
import type { PlanContentResponse, SectionResult } from "../types/content";
import { PolishPanel } from "./PolishPanel";
import "./ContentPlanner.css";

// ΓöÇΓöÇΓöÇ Section type ΓåÆ icon/label/color ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

const TYPE_CONFIG: Record<string, { label: string; color: string; icon: string }> = {
  intro:          { label: "Introduction", color: "#8b5cf6", icon: "ΓåÆ" },
  body_how_to:    { label: "How-To",       color: "#10b981", icon: "ΓÜÖ" },
  body_comparison:{ label: "Comparison",    color: "#22d3ee", icon: "Γƒ╖" },
  body_explanation:{ label: "Explanation", color: "#f59e0b", icon: "Γùê" },
  body_list:      { label: "List",         color: "#f59e0b", icon: "Γëí" },
  faq:            { label: "FAQ",          color: "#22d3ee", icon: "?" },
  conclusion:     { label: "Conclusion",  color: "#ef4444", icon: "Γ£ô" },
};

function typeLabel(t: string) {
  return TYPE_CONFIG[t]?.label ?? t.replace(/_/g, " ");
}
function typeColor(t: string) {
  return TYPE_CONFIG[t]?.color ?? "var(--primary)";
}
function typeIcon(t: string) {
  return TYPE_CONFIG[t]?.icon ?? "Γùå";
}

// ΓöÇΓöÇΓöÇ Section badge ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

function SectionTypeBadge({ type }: { type: string }) {
  return (
    <span
      className="section-type-badge"
      style={{ color: typeColor(type), borderColor: typeColor(type) + "40" }}
    >
      {typeIcon(type)} {typeLabel(type)}
    </span>
  );
}

// ΓöÇΓöÇΓöÇ Tree node ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

function TreeNode({ section, index }: { section: SectionResult; index: number }) {
  // isIntro / isConclusion / ctaColor reserved for future layout logic
  const _isIntro    = index === 0;
  const _isConclusion = index > 0 && (section.type === "conclusion" || index === 0);
  const _ctaColor = section.cta ? "var(--green)" : "transparent";
  void _isIntro; void _isConclusion; void _ctaColor; // suppress unused warnings

  return (
    <div className="tree-node">
      {/* Connector line */}
      {index > 0 && <div className="tree-connector" />}

      <div className="tree-card" style={{ borderLeftColor: typeColor(section.type) }}>
