  onPublish?: (articleTitle: string, articleContent: string) => void;
}

export function ContentPlannerPanel({ plan, onPublish }: ContentPlannerPanelProps) {
  // AI Writer draft state ΓÇö populated only via AI polish flow
  const [writerDraft, setWriterDraft] = useState("");
  const [generating, setGenerating] = useState(false);
  const [writing, setWriting] = useState(false);

  const handlePolishAccept = (humanized: string) => {
    setWriterDraft(humanized);
  };

  const handlePolishPublish = (humanized: string) => {
    onPublish?.(
      plan.meta.title_options[0] || plan.topic,
      humanized
    );
  };

  const handleGenerateDraft = () => {
    setGenerating(true);
    const draft = plan.sections.map((s) => {
      const intro = s.strategic_angle ? `${s.strategic_angle}\n\n` : "";
      const hook = s.engagement_hook ? `> ${s.engagement_hook}\n\n` : "";
      const body = `[Viß║┐t nß╗Öi dung cho phß║ºn "${s.heading}" tß║íi ─æ├óy ΓÇö khoß║úng ${s.word_target} tß╗½. `;
      const gaps = s.knowledge_gaps.length > 0
        ? `Chß╗º ─æß╗ü cß║ºn ─æß╗ü cß║¡p: ${s.knowledge_gaps.join(", ")}.`
        : "";
      const cta = s.cta ? ` CTA: ${s.cta.toUpperCase()}.` : "";
      return `## ${s.heading}\n\n${hook}${intro}${body}${gaps}${cta}]`;
    }).join("\n\n---\n\n");

    const fullDraft = `# ${plan.meta.title_options[0] || plan.topic}\n\n${draft}`;
    setWriterDraft(fullDraft);
    setTimeout(() => setGenerating(false), 500);
  };

  const handleWriteFull = async () => {
    setWriting(true);
    setWriterDraft("ΓÅ│ AI ─æang viß║┐t b├ái... Vui l├▓ng chß╗¥ 1-2 ph├║t...");
    try {
      const response = await fetch("http://localhost:8000/api/content/write-full", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          topic: plan.topic,
          sections: plan.sections
        })
      });
      const data = await response.json();
      if (data.error) {
        setWriterDraft(`Γ¥î Lß╗ùi: ${data.error}`);
      } else {
        const fullContent = `# ${plan.meta.title_options[0] || plan.topic}\n\n${data.content}`;
        setWriterDraft(fullContent);
      }
    } catch (e: any) {
      setWriterDraft(`Γ¥î Lß╗ùi mß║íng: ${e.message}`);
    }
    setWriting(false);
  };

  // Warn if user tries to publish the outline skeleton directly
  const handleOutlinePublish = () => {
    const placeholders = plan.sections
      .map((s) => `[Write section ${s.section_number} here`)
      .join(", ");
    const confirmed = window.confirm(
      `ΓÜá∩╕Å Publishing this outline will send placeholder content:\n"${placeholders}"\n\n` +
      `Use the AI Writer tab to generate full article sections before publishing. ` +
      `Are you sure you want to publish anyway?`
    );
    if (!confirmed) return;
    const outlineText = plan.sections
      .map((s) => `## ${s.heading}\n\n[Write section ${s.section_number} here ΓÇö ${s.word_target} words]`)
      .join("\n\n");
    onPublish?.(
      plan.meta.title_options[0] || plan.topic,
      `# ${plan.topic}\n\n${outlineText}`
    );
  };

  return (
    <div className="result-panel">
      <div className="result-header">
        <div className="result-meta">
          <h2 className="result-title">AI Content Outline</h2>
          <p className="result-keyword">
