            >
              {generating ? "ΓÅ│ ─Éang tß║ío..." : "≡ƒôä Tß║ío d├án ├╜ trß╗æng"}
            </button>
            <button
              type="button"
              onClick={handleWriteFull}
              disabled={generating || writing}
              style={{
                fontSize: "12px",
                padding: "5px 12px",
