import { useState, useRef, useCallback } from "react";
import { API_BASE } from "../lib/apiConfig";

const FORMAT_ICONS: Record<string, string> = {
  ".pdf": "≡ƒôä", ".docx": "≡ƒô¥", ".doc": "≡ƒô¥", ".pptx": "≡ƒôè",
  ".xlsx": "≡ƒôê", ".xls": "≡ƒôê", ".csv": "≡ƒôï", ".html": "≡ƒîÉ",
  ".htm": "≡ƒîÉ", ".json": "≡ƒöº", ".xml": "≡ƒôª", ".txt": "≡ƒôâ",
  ".md": "≡ƒôæ", ".epub": "≡ƒôÜ", ".zip": "≡ƒù£∩╕Å", ".jpg": "≡ƒû╝∩╕Å",
  ".jpeg": "≡ƒû╝∩╕Å", ".png": "≡ƒû╝∩╕Å", ".mp3": "≡ƒÄ╡", ".wav": "≡ƒÄ╡",
};

interface ConvertResult {
  markdown: string;
  filename?: string;
  url?: string;
  word_count: number;
  char_count: number;
  extension?: string;
  success: boolean;
  error?: string;
}

export default function FileConverter() {
  const [mode, setMode] = useState<"file" | "url">("file");
  const [url, setUrl] = useState("");
  const [result, setResult] = useState<ConvertResult | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const [dragOver, setDragOver] = useState(false);
  const [selectedFile, setSelectedFile] = useState<File | null>(null);
  const [copied, setCopied] = useState(false);
  const fileRef = useRef<HTMLInputElement>(null);

  const handleFileDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setDragOver(false);
    const file = e.dataTransfer.files[0];
    if (file) setSelectedFile(file);
  }, []);

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) setSelectedFile(file);
  };

  const convertFile = async () => {
    if (!selectedFile) return;
    setLoading(true);
    setError("");
    setResult(null);
    try {
      const formData = new FormData();
      formData.append("file", selectedFile);
      const resp = await fetch(`${API_BASE}/convert/file`, {
        method: "POST",
        body: formData,
      });
      if (!resp.ok) throw new Error(`Server error: ${resp.status}`);
      const data: ConvertResult = await resp.json();
      if (!data.success) throw new Error(data.error || "Conversion failed");
      setResult(data);
    } catch (err: any) {
      setError(err.message || "Lß╗ùi chuyß╗ân ─æß╗òi file");
    } finally {
      setLoading(false);
    }
  };

  const convertUrl = async () => {
    if (!url.trim()) return;
    setLoading(true);
    setError("");
    setResult(null);
    try {
      const resp = await fetch(`${API_BASE}/convert/url`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ url: url.trim() }),
      });
      if (!resp.ok) throw new Error(`Server error: ${resp.status}`);
      const data: ConvertResult = await resp.json();
      if (!data.success) throw new Error(data.error || "Conversion failed");
      setResult(data);
    } catch (err: any) {
      setError(err.message || "Lß╗ùi chuyß╗ân ─æß╗òi URL");
    } finally {
      setLoading(false);
    }
  };

  const copyToClipboard = () => {
    if (!result?.markdown) return;
    navigator.clipboard.writeText(result.markdown);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const downloadMarkdown = () => {
    if (!result?.markdown) return;
    const name = result.filename
      ? result.filename.replace(/\.[^.]+$/, ".md")
      : "converted.md";
    const blob = new Blob([result.markdown], { type: "text/markdown" });
    const a = document.createElement("a");
    a.href = URL.createObjectURL(blob);
    a.download = name;
    a.click();
    URL.revokeObjectURL(a.href);
  };

  const formatSize = (bytes: number) => {
    if (bytes < 1024) return `${bytes} B`;
    if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
    return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
  };

  return (
    <div className="audit-form" style={{ maxWidth: 900 }}>
      <h2 style={{ marginBottom: 6, display: "flex", alignItems: "center", gap: 10 }}>
        <span style={{ fontSize: 28 }}>≡ƒôÄ</span> File Converter
        <span style={{
          fontSize: 11, background: "linear-gradient(135deg, #8b5cf6, #06b6d4)",
          padding: "3px 10px", borderRadius: 12, fontWeight: 600, marginLeft: 8
        }}>MarkItDown</span>
      </h2>
      <p style={{ color: "var(--text-m)", fontSize: 13, marginBottom: 20 }}>
        Chuyß╗ân ─æß╗òi PDF, Word, Excel, PowerPoint, HTML, ß║únh ΓåÆ Markdown ─æß╗â ph├ón t├¡ch SEO
      </p>

      {/* Mode Toggle */}
      <div style={{ display: "flex", gap: 8, marginBottom: 20 }}>
        <button
          className={`submit-btn ${mode === "file" ? "" : "secondary"}`}
          onClick={() => { setMode("file"); setResult(null); setError(""); }}
          style={mode !== "file" ? {
            background: "rgba(255,255,255,0.05)", border: "1px solid rgba(255,255,255,0.1)"
          } : {}}
