import { useState, useEffect, useCallback } from "react";
import { API_BASE } from "../lib/apiConfig";
import {
  LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip,
  ResponsiveContainer, ReferenceLine
} from "recharts";

interface TrackedKeyword {
  keyword: string;
  tag: string;
  position: number | null;
  previous_position: number | null;
  change: number | null;
  clicks: number;
  impressions: number;
  ctr: number;
  source: string;
  last_checked: string | null;
}

interface HistoryPoint {
  date: string;
  position: number;
  clicks: number;
  impressions: number;
}

interface Alert {
  keyword: string;
  current_position: number;
  previous_position: number;
  drop: number;
  severity: string;
}

export function RankTracker() {
  const [keywords, setKeywords] = useState<TrackedKeyword[]>([]);
  const [newKeyword, setNewKeyword] = useState("");
  const [newTag, setNewTag] = useState("");
  const [loading, setLoading] = useState(false);
  const [syncing, setSyncing] = useState(false);
  const [selectedKw, setSelectedKw] = useState<string | null>(null);
  const [history, setHistory] = useState<HistoryPoint[]>([]);
  const [historyDays, setHistoryDays] = useState(30);
  const [error, setError] = useState("");
  const [tags, setTags] = useState<string[]>([]);
  const [activeTag, setActiveTag] = useState("");
  const [alerts, setAlerts] = useState<Alert[]>([]);
  const [showImport, setShowImport] = useState(false);
  const [csvText, setCsvText] = useState("");
  const [importResult, setImportResult] = useState("");

  const fetchKeywords = useCallback(async () => {
    try {
      const params = activeTag ? `?tag=${encodeURIComponent(activeTag)}` : "";
      const r = await fetch(`${API_BASE}/rank-tracker/keywords${params}`);
      const d = await r.json();
      setKeywords(d.keywords || []);
    } catch { /* ignore */ }
  }, [activeTag]);

  const fetchTags = async () => {
    try {
      const r = await fetch(`${API_BASE}/rank-tracker/tags`);
      const d = await r.json();
      setTags(d.tags || []);
