      </div>

      {/* CSV Import panel */}
      {showImport && (
        <div className="rt-import-panel">
          <textarea className="spin-textarea" rows={4} placeholder={`D├ín CSV: keyword,tag\nmitsubishi xpander,xe\nbß║úng gi├í mitsubishi 2025,gi├í`}
            value={csvText} onChange={e => setCsvText(e.target.value)} />
          <div style={{ display: "flex", gap: 8, marginTop: 8 }}>
            <button className="rt-btn rt-btn-add" onClick={handleImportCsv} disabled={!csvText.trim()}>Import</button>
