                  <td>{kw.clicks}</td>
                  <td>{kw.impressions.toLocaleString()}</td>
                  <td>{kw.ctr > 0 ? `${kw.ctr}%` : "ΓÇö"}</td>
                  <td>
                    <span className={`rt-source-badge ${kw.source}`}>
                      {kw.source === "gsc" ? "GSC" : kw.source === "pending" ? "Chß╗¥" : kw.source}
                    </span>
                  </td>
                  <td>
                    <button className="rt-del-btn" onClick={e => { e.stopPropagation(); removeKeyword(kw.keyword); }} title="X├│a">
                      <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M18 6L6 18M6 6l12 12" /></svg>
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      ) : (
        <div className="rt-empty">
          <svg width="48" height="48" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" opacity="0.3">
            <polyline points="22 7 13.5 15.5 8.5 10.5 2 17" /><polyline points="16 7 22 7 22 13" />
          </svg>
          <p>Ch╞░a c├│ tß╗½ kh├│a n├áo. Th├¬m tß╗½ kh├│a hoß║╖c import CSV.</p>
        </div>
      )}

      {/* History chart */}
      {selectedKw && (
        <div className="rt-chart-section">
          <div className="rt-chart-header">
            <h3 className="section-title">≡ƒôê Lß╗ïch sß╗¡: <em>{selectedKw}</em></h3>
            <div className="rt-days-selector">
              {[7, 14, 30, 90].map(d => (
                <button key={d} className={`rt-day-btn ${historyDays === d ? "active" : ""}`}
                  onClick={() => { setHistoryDays(d); loadHistory(selectedKw); }}>{d} ng├áy</button>
              ))}
            </div>
          </div>
          {history.length > 0 ? (
            <div className="rt-chart">
              <ResponsiveContainer width="100%" height={280}>
                <LineChart data={history} margin={{ top: 10, right: 20, bottom: 10, left: 10 }}>
                  <CartesianGrid strokeDasharray="3 3" stroke="rgba(255,255,255,0.06)" />
                  <XAxis dataKey="date" tick={{ fill: "var(--text-dim)", fontSize: 11 }} />
                  <YAxis reversed domain={[1, "auto"]} tick={{ fill: "var(--text-dim)", fontSize: 11 }}
                    label={{ value: "Vß╗ï tr├¡", angle: -90, position: "insideLeft", fill: "var(--text-dim)", fontSize: 11 }} />
