                    labelStyle={{ color: "var(--text-h)" }} />
                  <ReferenceLine y={10} stroke="rgba(245,158,11,0.3)" strokeDasharray="3 3" label={{ value: "Top 10", fill: "#f59e0b", fontSize: 10 }} />
                  <ReferenceLine y={3} stroke="rgba(34,197,94,0.3)" strokeDasharray="3 3" label={{ value: "Top 3", fill: "#22c55e", fontSize: 10 }} />
                  <Line type="monotone" dataKey="position" stroke="#8b5cf6" strokeWidth={2.5}
                    dot={{ fill: "#8b5cf6", r: 4 }} activeDot={{ r: 6, fill: "#a78bfa" }} />
                </LineChart>
              </ResponsiveContainer>
            </div>
          ) : (
            <div className="rt-no-history"><p>Ch╞░a c├│ dß╗» liß╗çu. Nhß║Ñn <strong>─Éß╗ông bß╗Ö GSC</strong> ─æß╗â lß║Ñy dß╗» liß╗çu.</p></div>
          )}
        </div>
      )}
    </div>
  );
}

import { useState } from "react";
import { API_BASE } from "../lib/apiConfig";

interface ReportSection {
  title: string;
  score?: number;
  max?: number;
  grade?: string;
  error?: string;
  load_time?: number;
  critical_count?: number;
  warning_count?: number;
  issues?: any[];
  recommendations?: any[];
  total_tracked?: number;
  top_keywords?: any[];
  dropping?: any[];
}

interface Report {
  url: string;
  generated_at: string;
  overall_score: number;
  overall_grade: string;
  ai_summary: string;
  sections: Record<string, ReportSection>;
  all_issues: any[];
  total_issues: number;
}

export function ReportGenerator() {
  const [url, setUrl] = useState("");
  const [keyword, setKeyword] = useState("");
  const [loading, setLoading] = useState(false);
  const [report, setReport] = useState<Report | null>(null);
  const [error, setError] = useState("");

  const handleGenerate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!url.trim()) return;
    setLoading(true); setError(""); setReport(null);
    try {
      const r = await fetch(`${API_BASE}/report/generate`, {
        method: "POST", headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ url: url.trim(), keyword: keyword.trim() }),
      });
      const d = await r.json();
      if (d.error) setError(d.error); else setReport(d);
    } catch (e: any) { setError(e.message); }
    setLoading(false);
  };

  const exportReport = async (format: "txt" | "pdf" = "txt") => {
    if (format === "pdf" && report) {
      // Generate styled HTML for PDF
      const html = `<!DOCTYPE html><html><head><meta charset="utf-8">
<title>SEO Report ΓÇö ${report.url}</title>
<style>
  body { font-family: 'Segoe UI', sans-serif; color: #222; max-width: 800px; margin: 0 auto; padding: 40px 30px; }
  h1 { color: #7c3aed; font-size: 22px; border-bottom: 2px solid #7c3aed; padding-bottom: 8px; }
  h2 { color: #3b82f6; font-size: 16px; margin-top: 24px; }
  .grade { font-size: 48px; font-weight: 800; text-align: center; margin: 20px 0; }
  .grade-A { color: #22c55e; } .grade-B { color: #3b82f6; } .grade-C { color: #f59e0b; } .grade-D { color: #ef4444; }
  table { width: 100%; border-collapse: collapse; margin: 12px 0; }
  th, td { text-align: left; padding: 8px 12px; border-bottom: 1px solid #e5e7eb; font-size: 13px; }
  th { background: #f3f4f6; font-weight: 600; }
  .issue { padding: 6px 12px; margin: 4px 0; border-left: 3px solid; font-size: 13px; }
  .critical { border-color: #ef4444; background: #fef2f2; }
  .warning { border-color: #f59e0b; background: #fffbeb; }
  .info { border-color: #3b82f6; background: #eff6ff; }
  .summary { background: #f5f3ff; border: 1px solid #ddd6fe; border-radius: 8px; padding: 16px; margin: 16px 0; font-size: 14px; line-height: 1.7; }
  .footer { text-align: center; color: #9ca3af; font-size: 11px; margin-top: 40px; border-top: 1px solid #e5e7eb; padding-top: 12px; }
</style></head><body>
<h1>≡ƒôè B├ío C├ío SEO ΓÇö ${report.url}</h1>
<p style="color:#666">Ng├áy: ${report.generated_at?.slice(0, 10)} ┬╖ Keyword: ${url.split("//")[1]?.split("/")[0] || ""}</p>
<div class="grade grade-${report.overall_grade}">${report.overall_score}/100 (${report.overall_grade})</div>
<div class="summary"><strong>≡ƒñû AI T├│m tß║»t:</strong><br>${report.ai_summary}</div>
<h2>≡ƒôê Chi tiß║┐t theo module</h2>
<table><thead><tr><th>Module</th><th>─Éiß╗âm</th><th>Grade</th></tr></thead><tbody>
${Object.entries(report.sections).map(([, sec]) =>
  sec.score != null ? `<tr><td>${sec.title}</td><td>${sec.score}/${sec.max || 100}</td><td>${sec.grade || ""}</td></tr>` : ""
).join("")}
</tbody></table>
<h2>≡ƒöì Vß║Ñn ─æß╗ü cß║ºn sß╗¡a (${report.total_issues})</h2>
${report.all_issues.slice(0, 15).map(issue =>
  `<div class="issue ${issue.severity}">${{critical:"≡ƒö┤",warning:"≡ƒƒí",info:"≡ƒö╡"}[issue.severity as string] || "ΓÜ¬"} <strong>${issue.category}</strong>: ${issue.message}${issue.fix ? ` ΓåÆ ${issue.fix}` : ""}</div>`
).join("")}
<div class="footer">Generated by AI Marketing Hub v3.1.0 ┬╖ ${new Date().toISOString().slice(0,10)}</div>
</body></html>`;
      const w = window.open("", "_blank");
      if (w) { w.document.write(html); w.document.close(); setTimeout(() => w.print(), 500); }
      return;
    }
    try {
      const r = await fetch(`${API_BASE}/report/export`, {
        method: "POST", headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ url: url.trim(), keyword: keyword.trim() }),
      });
      const text = await r.text();
      const blob = new Blob([text], { type: "text/plain;charset=utf-8" });
      const a = document.createElement("a");
      a.href = URL.createObjectURL(blob);
      a.download = `seo_report_${url.split("//")[1]?.split("/")[0] || "report"}.txt`;
      a.click();
    } catch { /* ignore */ }
  };

  const gradeColor = (g: string) => ({ A: "#22c55e", B: "#3b82f6", C: "#f59e0b", D: "#ef4444" }[g] || "#888");

  return (
    <div className="geo-optimizer">
      <form className="audit-form" onSubmit={handleGenerate}>
        <div className="hint-box">≡ƒôè <strong>AI Report Generator:</strong> Tß║ío b├ío c├ío SEO tß╗òng hß╗úp tß╗½ Technical SEO + GEO + Rankings vß╗¢i AI summary.</div>
        <div className="input-row">
          <div className="input-group" style={{ flex: 2 }}>
            <label className="input-label">URL</label>
            <div className="input-wrap">
              <svg className="input-icon" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0z" /><path d="M3.6 9h16.8M3.6 15h16.8" /></svg>
              <input type="url" className="text-input" value={url} onChange={e => setUrl(e.target.value)} required />
            </div>
          </div>
          <div className="input-group" style={{ flex: 1 }}>
            <label className="input-label">Tß╗½ kh├│a</label>
            <div className="input-wrap">
              <svg className="input-icon" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><circle cx="11" cy="11" r="8" /><path d="m21 21-4.35-4.35" /></svg>
              <input type="text" className="text-input" value={keyword} onChange={e => setKeyword(e.target.value)} />
            </div>
          </div>
          <button className={`submit-btn ${loading ? "loading" : ""}`} type="submit" disabled={loading} style={{ alignSelf: "flex-end" }}>
            {loading ? (<><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" className="spin-icon"><path d="M3 12a9 9 0 1 0 9-9 9.75 9.75 0 0 0-6.74 2.74L3 8" /></svg> ─Éang tß║ío...</>) : "≡ƒôè Tß║ío b├ío c├ío"}
          </button>
        </div>
        {error && <p className="error-msg">{error}</p>}
      </form>

      {report && (
        <div className="geo-result">
