import { useState, useEffect, useCallback } from "react";
import { API_BASE } from "../lib/apiConfig";
import "./SatelliteManager.css";

interface SatSite {
  id: string;
  name: string;
  url: string;
  platform: string;
  blog_id: string;
  total_posts: number;
  status: string;
  created_at: string;
}

interface SatPost {
  id: string;
  site_id: string;
  site_name: string;
  platform: string;
  title: string;
  post_url: string;
  backlink_url: string;
  backlink_keyword: string;
  status: string;
  error: string;
  posted_at: string;
  indexed: boolean;
}

interface SpinVersion {
  version: number;
  content_text: string;
  content_html: string;
  uniqueness_percent: number;
  word_count: number;
}

type TabId = "sites" | "spinpost" | "history";

export function SatelliteManager() {
  const [tab, setTab] = useState<TabId>("sites");
  const [sites, setSites] = useState<SatSite[]>([]);
  const [posts, setPosts] = useState<SatPost[]>([]);
  const [loading, setLoading] = useState(false);

  // Add site form
  const [showAddForm, setShowAddForm] = useState(false);
  const [newSite, setNewSite] = useState({
    name: "", url: "", platform: "blogger", blog_id: "",
    wp_username: "", wp_app_password: "",
  });

  // Spin & Post form
  const [spinForm, setSpinForm] = useState({
    content: "", title: "", spin_level: "medium", spin_tone: "neutral",
    backlink_url: "https://binhphuocmitsubishi.com/",
    backlink_keyword: "mitsubishi b├¼nh ph╞░ß╗¢c",
    preserve_keywords: "",
  });
  const [selectedSites, setSelectedSites] = useState<string[]>([]);
  const [spinLoading, setSpinLoading] = useState(false);
  const [spinResults, setSpinResults] = useState<any>(null);

  // Preview
  const [previewVersions, setPreviewVersions] = useState<SpinVersion[]>([]);
  const [activePreview, setActivePreview] = useState(0);

  // ΓöÇΓöÇ Fetch Data ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

  const fetchSites = useCallback(async () => {
    try {
      const r = await fetch(`${API_BASE}/satellite/sites`);
      if (r.ok) {
        const d = await r.json();
        setSites(d.sites || []);
      }
    } catch { /* silent */ }
  }, []);

  const fetchPosts = useCallback(async () => {
    try {
      const r = await fetch(`${API_BASE}/satellite/posts?limit=50`);
      if (r.ok) {
        const d = await r.json();
        setPosts(d.posts || []);
      }
    } catch { /* silent */ }
  }, []);

  useEffect(() => {
    fetchSites();
    fetchPosts();
  }, [fetchSites, fetchPosts]);

  // ΓöÇΓöÇ Site CRUD ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

  const handleAddSite = async () => {
    if (!newSite.name || !newSite.url) return;
    setLoading(true);
    try {
      const r = await fetch(`${API_BASE}/satellite/sites`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(newSite),
      });
      if (r.ok) {
        setShowAddForm(false);
        setNewSite({ name: "", url: "", platform: "blogger", blog_id: "", wp_username: "", wp_app_password: "" });
