        </div>
        <div className="sat-stat">
          <div className="sat-stat-value">{publishedPosts}</div>
          <div className="sat-stat-label">B├ái ─æ├ú ─æ─âng</div>
        </div>
        <div className="sat-stat">
          <div className="sat-stat-value">{totalPosts > 0 ? Math.round(publishedPosts / totalPosts * 100) : 0}%</div>
          <div className="sat-stat-label">Tß╗╖ lß╗ç th├ánh c├┤ng</div>
        </div>
        <div className="sat-stat">
          <div className="sat-stat-value">{posts.filter(p => p.indexed).length}</div>
          <div className="sat-stat-label">─É├ú index</div>
        </div>
      </div>

      {/* Tabs */}
      <div className="sat-tabs">
        <button className={`sat-tab ${tab === "sites" ? "active" : ""}`} onClick={() => setTab("sites")}>
          ≡ƒîÉ Sites <span className="sat-badge">{sites.length}</span>
        </button>
        <button className={`sat-tab ${tab === "spinpost" ? "active" : ""}`} onClick={() => setTab("spinpost")}>
          ≡ƒöä Spin & Post
        </button>
        <button className={`sat-tab ${tab === "history" ? "active" : ""}`} onClick={() => setTab("history")}>
          ≡ƒôï Lß╗ïch sß╗¡ <span className="sat-badge">{posts.length}</span>
        </button>
      </div>

      {/* ΓöÇΓöÇ Tab: Sites ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */}
      {tab === "sites" && (
        <div className="sat-card">
          <div className="sat-card-header">
