interface SchemaItem {
  type: string;
  status: string;       // "valid" | "warning" | "error"
  errors: string[];
  warnings: string[];
  raw: Record<string, any>;
}

interface ValidationResult {
  url?: string;
  schemas: SchemaItem[];
  total_schemas: number;
  valid_count: number;
  warning_count: number;
  error_count: number;
}

type InputMode = "url" | "paste";

