  if (status === "warning") return "Cß║únh b├ío";
  return "Lß╗ùi";
}

/** Simple client-side JSON-LD validation */
function validateJsonLdLocally(jsonStr: string): ValidationResult {
  let parsed: any;
  try {
    parsed = JSON.parse(jsonStr);
  } catch {
    return {
      schemas: [{ type: "Unknown", status: "error", errors: ["JSON kh├┤ng hß╗úp lß╗ç ΓÇö kiß╗âm tra lß║íi c├║ ph├íp"], warnings: [], raw: {} }],
      total_schemas: 0, valid_count: 0, warning_count: 0, error_count: 1,
    };
  }

  // Normalize: single object ΓåÆ array
  const items: any[] = Array.isArray(parsed) ? parsed : [parsed];
  const schemas: SchemaItem[] = items.map(item => {
    const errors: string[] = [];
    const warnings: string[] = [];
    const type = item["@type"] || "Unknown";

    // Basic checks
    if (!item["@context"]) errors.push("Thiß║┐u @context (n├¬n d├╣ng https://schema.org)");
    if (!item["@type"]) errors.push("Thiß║┐u @type");
    if (item["@context"] && !String(item["@context"]).includes("schema.org")) {
      warnings.push("@context kh├┤ng phß║úi schema.org");
    }

    // Common required fields checks
    if (type === "Article" || type === "BlogPosting") {
      if (!item.headline) warnings.push("Thiß║┐u headline");
      if (!item.author) warnings.push("Thiß║┐u author");
      if (!item.datePublished) warnings.push("Thiß║┐u datePublished");
    }
    if (type === "Product") {
      if (!item.name) errors.push("Thiß║┐u name (bß║»t buß╗Öc)");
      if (!item.offers) warnings.push("Thiß║┐u offers");
    }
    if (type === "Organization") {
      if (!item.name) errors.push("Thiß║┐u name (bß║»t buß╗Öc)");
      if (!item.url) warnings.push("Thiß║┐u url");
    }

    const status = errors.length > 0 ? "error" : warnings.length > 0 ? "warning" : "valid";
    return { type, status, errors, warnings, raw: item };
  });

  return {
    schemas,
    total_schemas: schemas.length,
    valid_count: schemas.filter(s => s.status === "valid").length,
    warning_count: schemas.filter(s => s.status === "warning").length,
    error_count: schemas.filter(s => s.status === "error").length,
  };
}

/** Syntax-highlight JSON string for display */
function highlightJson(json: string): string {
  return json
    .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
    .replace(/"(\\u[a-fA-F0-9]{4}|\\[^u]|[^"\\])*"(\s*:)?/g, (match) => {
      let cls = "json-string";  // string value
      if (match.endsWith(":")) cls = "json-key";
      else if (/true|false/.test(match)) cls = "json-bool";
      else if (/null/.test(match)) cls = "json-null";
      return `<span class="${cls}">${match}</span>`;
    })
    .replace(/\b(\d+\.?\d*)\b/g, '<span class="json-number">$1</span>');
}

