    setLoading(true);
    try {
      const [hRes, sRes] = await Promise.all([
        fetch(`${API}/api/usage-history?limit=100${filter ? `&endpoint=${filter}` : ""}`),
        fetch(`${API}/api/usage-stats`),
      ]);
      if (hRes.ok) setHistory(await hRes.json());
      if (sRes.ok) setStats(await sRes.json());
