            <div style={{ fontSize: 24, fontWeight: 700, color: "var(--text-h)" }}>{stats.total_calls}</div>
            <div style={{ fontSize: 11, color: "rgba(255,255,255,0.5)", marginTop: 4 }}>Tß╗òng API calls</div>
